import{c as r,Q as a,j as t,m as l}from"./chunks/framework.DOi4mjdC.js";const n="/assets/%E5%9B%BE1-AI-Core%E5%86%85%E9%83%A8%E5%B9%B6%E8%A1%8C%E8%AE%A1%E7%AE%97%E6%9E%B6%E6%9E%84%E6%8A%BD%E8%B1%A1%E7%A4%BA%E6%84%8F%E5%9B%BE-35.CGV2ZclC.png",s="/assets/%E9%80%9A%E8%BF%87SetNextTaskStart%E5%AE%9E%E7%8E%B0%E5%B9%B6%E8%A1%8C%E7%A4%BA%E6%84%8F%E5%9B%BE.BDAxJyEP.png",i="/assets/%E9%80%9A%E8%BF%87WaitPreTaskEnd%E5%AE%9E%E7%8E%B0%E5%B9%B6%E8%A1%8C%E7%A4%BA%E6%84%8F%E5%9B%BE.BSHp4Ocf.png",g=JSON.parse('{"title":"SuperKernel开发","description":"","frontmatter":{},"headers":[{"level":1,"title":"SuperKernel开发","slug":"superkernel开发"},{"level":2,"title":"自定义算子支持SuperKernel","slug":"自定义算子支持superkernel"},{"level":2,"title":"性能优化建议","slug":"性能优化建议"}],"relativePath":"guide/编程指南/高级编程/高级特性/算子入图开发/SuperKernel开发.md","filePath":"guide/编程指南/高级编程/高级特性/算子入图开发/SuperKernel开发.md"}'),p={name:"guide/编程指南/高级编程/高级特性/算子入图开发/SuperKernel开发.md"};function o(c,e,h,d,k,u){return a(),t("div",null,[...e[0]||(e[0]=[l(`<h1 id="superkernel开发" tabindex="-1">SuperKernel开发 <a class="header-anchor" href="#superkernel开发" aria-label="Permalink to &quot;SuperKernel开发&quot;">​</a></h1><p>SuperKernel是一种算子的二进制融合技术，与源码融合不同，它聚焦于内核函数 (Kernel) 的二进制的调度方案，展开深度优化，于已编译的二进制代码基础上融合创建一个超级Kernel函数（SuperKernel），以调用子函数的方式调用多个其他内核函数，也就是子Kernel。相对于单算子下发，SuperKernel技术可以减少任务调度等待时间和调度开销，同时利用Task间隙资源进一步优化算子头开销。</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p></p><ul><li>SuperKernel仅适用于静态图场景。</li><li>SuperKernel适用于如下型号： <ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li><li>Ascend 950PR/Ascend 950DT</li></ul></li></ul></div><h2 id="自定义算子支持superkernel" tabindex="-1">自定义算子支持SuperKernel <a class="header-anchor" href="#自定义算子支持superkernel" aria-label="Permalink to &quot;自定义算子支持SuperKernel&quot;">​</a></h2><p>自定义算子支持SuperKernel与普通算子在开发流程上并无显著差异，但需注意一些<strong>特定约束</strong>（详见下文）。当前SuperKernel特性仅支持在Pytorch框架使用，所以完成<a href="./基本开发流程.html">算子入图（GE图）开发</a>开发后，还需要参考《PyTorch图模式使用指南(TorchAir)》中的“自定义算子入图”章节，完成Pytorch入图。同时，TorchAir提供标定SuperKernel范围的能力，用户可根据实际业务需求对融合范围内的算子进行标记和优化配置。具体内容请参考<a href="https://www.hiascend.com/document/redirect/pytorchuserguide" target="_blank" rel="noreferrer">《Ascend Extension for PyTorch》</a>中“Pytorch图模式使用(TorchAir) &gt; max-autotune模式功能 &gt; 图内标定SuperKernel范围”章节。</p><p>开发时的<strong>特定约束</strong>说明如下：</p><ul><li><p>自定义算子若进行全核同步，需注意子Kernel（即该算子）启动的核数与SuperKernel的核数一致。若子Kernel启动的核数少于SuperKernel的核数，全核同步会等待所有核完成，导致卡住超时。</p><p>注：SuperKernel启动核数为子Kernel的最大启动核数。假设SuperKernel包括算子a（启动核数为4）和算子b（启动核数为2），此时SuperKernel启动核数为4。</p><ul><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SyncAll.md" target="_blank" rel="noreferrer">SyncAll</a>时，为了解决该问题，可以通过在标定SuperKernel范围时开启feed-sync-all功能，此时系统会在SuperKernel内子Kernel的其余核中插入SyncAll指令，防止卡住超时。</li><li>若使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/CrossCoreSetFlag(ISASI).md" target="_blank" rel="noreferrer">CrossCoreSetFlag</a>和<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/CrossCoreWaitFlag(ISASI).md" target="_blank" rel="noreferrer">CrossCoreWaitFlag</a>硬同步接口实现全核同步，仅支持子Kernel启动核数与SuperKernel核数相同。</li></ul></li><li><p>若自定义算子的Kernel类型设置为KERNEL_TYPE_MIX_AIC_1_1，因为SuperKernel会根据启动核数等信息调整SuperKernel的启动比例，此时需特别注意该算子也可以适应SuperKernel的1:2启动比例，确保AIC与AIV之间的硬同步操作正确执行。比如：算子内部使用了AIC与AIV之间的硬同步接口（CrossCoreSetFlag和CrossCoreWaitFlag），不要单独指定某些AIV核调用硬同步接口，使所有AIV核均调用硬同步接口，防止因为硬同步数量不匹配而导致卡死超时；使用Matmul高阶API时，算子逻辑应保证仅有一个AIV0核调用Matmul接口，防止启动两个AIV核之后出现AIV1核消息无法接收导致卡死超时。</p></li><li><p>在开发自定义算子时，开发者必须确保所有对GM的标量读写操作都按需正确插入<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DataCacheCleanAndInvalid.md" target="_blank" rel="noreferrer">DataCacheCleanAndInvalid</a>指令：在单算子编译场景下，毕昇编译器自动在算子末尾添加DataCacheCleanAndInvalid指令，刷新整个DCache（数据缓存）。在SuperKernel中，子Kernel被当做普通函数处理，编译器不会自动插入该指令来确保数据缓存一致性，开发者需要自行保证避免因容错机制改变而导致错误。</p><p>出于性能考虑，SuperKernel场景下Cache刷新机制如下：</p><p>如果开发者调用GlobalTensor的GetValue和SetValue接口对GM进行标量读写，SuperKernel编译时会自动在两个接口内部插入DataCacheCleanAndInvalid指令刷新单个Cache Line，保证一定的数据缓存一致性。不会在子Kernel调用前后插入DataCacheCleanAndInvalid。</p><p>如果开发者通过GlobalTensor的()运算符接口来获取值(读值时会插入DataCacheCleanAndInvalid指令刷新单个Cache Line保证数据缓存一致性)，但通过该接口直接改写了GlobalTensor对应位置的值时，则不会自动插入DataCacheCleanAndInvalid指令，开发者需要自行保证数据缓存一致性。比如:</p><div class="language-c++ vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c++</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">AscendC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::GlobalTensor</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;float&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> xGm;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">xGm.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">SetGlobalBuffer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((__gm__ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)(addr), length);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // addr 为GM地址，length为对应GM长度</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xGm</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 在获取值时，SuperKernel能够保证自动刷新cache line，但是写值时，相当于普通变量直接赋值，SuperKernel无法插入DataCacheCleanAndInvalid，需要用户保证数据缓存的一致性。</span></span></code></pre></div><p>同时，需要额外注意的是，过多调用GetValue和SetValue，在SuperKernel场景下会导致性能劣化，开发者需要尽量减少该接口调用。对于劣化过多的算子，SuperKernel提供了编译选项dcci-before-kernel-start、dcci-after-kernel-start、dcci-disable-on-kernel，可以关闭指定算子内GetValue/SetValue中自动插入的缓存刷新指令以提升模型性能，最终由模型用户决定是否在SuperKernel调用该算子前或后插入整个DCache刷新，编译选项具体内容请参考<a href="https://www.hiascend.com/document/detail/zh/Pytorch/710/modthirdparty/torchairuseguide/torchair_00035.html" target="_blank" rel="noreferrer">图内标定SuperKernel范围</a>中编译选项说明。</p><p>特别地，对于Tiling下沉场景，通常会涉及二进制复用优化，无法在线选择上述的Cache刷新机制，SuperKernel框架统一在每个子Kernel调用前后都插入DataCacheCleanAndInvalid指令，刷新整个DCache。不会在GetValue和SetValue自动进行缓存刷新。</p><p>Cache刷新机制示意图如下图所示：</p><p><img src="`+n+'" alt=""></p></li><li><p>在子Kernel中调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetBlockNum.md" target="_blank" rel="noreferrer">GetBlockNum</a>接口获取核数时，无论是否融合SuperKernel，获取的核数保持不变，不受SuperKernel启动核数的影响。因此，在使用该接口时，开发者无需特别关注SuperKernel的启动核数，使用方法和开发普通算子时一样。</p></li><li><p>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品中，在不使能SuperKernel场景下，<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Destroy.md" target="_blank" rel="noreferrer">TPipe::Destroy</a>接口内部最后会插入AscendC::PipeBarrier&lt;PIPE_ALL&gt;()指令，额外保障多个TPipe之间的流水同步；模型中绝大部分算子只会使用一个TPipe对象，在对象析构时会调用Destroy，为不阻塞<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetNextTaskStart.md" target="_blank" rel="noreferrer">SetNextTaskStart</a>和<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/WaitPreTaskEnd.md" target="_blank" rel="noreferrer">WaitPreTaskEnd</a>性能提升，SuperKernel场景下默认关闭了TPipe::Destroy中插入的AscendC::PipeBarrier&lt;PIPE_ALL&gt;()指令，所以当算子需要多个TPipe对象并手动调用Destroy函数时，开发者需自行保障TPipe对象间流水的同步。</p></li></ul><h2 id="性能优化建议" tabindex="-1">性能优化建议 <a class="header-anchor" href="#性能优化建议" aria-label="Permalink to &quot;性能优化建议&quot;">​</a></h2><ul><li><p>任务间同步</p><p>此外，开发者在进行Kernel侧编程时，可以通过调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/SetNextTaskStart.md" target="_blank" rel="noreferrer">SetNextTaskStart</a>和<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/WaitPreTaskEnd.md" target="_blank" rel="noreferrer">WaitPreTaskEnd</a>两个任务间接口，进一步提升性能。</p><ul><li><p>调用SetNextTaskStart后的指令可以和后续其他的子Kernel实现并行，提升整体性能。如<a href="#fig37581010773">图1</a>所示，SuperKernel按序调用子Kernel，为保证子Kernel之间数据互不干扰，会在子Kernel间插入算子间同步进行保序，子Kernel&lt;sub&gt;N-1&lt;/sub&gt;调用该接口后，之后的指令会和后续子Kernel&lt;sub&gt;N&lt;/sub&gt;实现并行。</p><p><strong>图 1</strong> 通过SetNextTaskStart实现并行示意图<br><img src="'+s+'" alt="" title="通过SetNextTaskStart实现并行示意图"></p></li><li><p>调用WaitPreTaskEnd前的指令可以和前序其他的子Kernel实现并行，提升整体性能。如<a href="#fig99271836191110">图2</a>所示，SuperKernel按序调用子Kernel，为保证子Kernel之间数据互不干扰，会在子Kernel间插入算子间同步进行保序，子Kernel&lt;sub&gt;N+1&lt;/sub&gt;调用该接口之前的指令会和前序子Kernel&lt;sub&gt;N&lt;/sub&gt;实现并行。</p><p><strong>图 2</strong> 通过WaitPreTaskEnd实现并行示意图<br><img src="'+i+'" alt="" title="通过WaitPreTaskEnd实现并行示意图"></p></li></ul></li><li><p>Tiling下沉场景，可以通过--op_relocatable_kernel_binary编译选项，开启二进制复用优化，提升编译性能，具体可参考<a href="./../Aclnn算子工程化开发/算子包编译/算子工程编译.html">LINK</a>。</p></li></ul>',9)])])}const S=r(p,[["render",o]]);export{g as __pageData,S as default};
